// План specs/billing.md 1.1 (#b20fe6). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение (@prod-safe).
// Подписка на доп. место отменена в Stripe → в строке «Extra companies» пометка «Cancels on Dec 12, 2026»
// (как «Cancels on» у основной подписки, #2185f2), платёж за это место не показывается в «Upcoming billing».
// Факты 17.11: «Cancels on Dec 12, 2026» совпадает со Stripe; «No upcoming charge is scheduled.».
// В конце периода (после 12.12.2026) строка исчезает — тест пропускается.
import { test, expect } from '../../fixtures';
import { ROLE, openBilling, subscriptionRow } from './billing-helpers';

test.describe('Billing — extra company cancellation (#b20fe6)', () => {
  test.skip(new Date() > new Date('2026-12-12T23:59:59Z'), 'после 12.12.2026 строка Extra companies исчезает (конец периода)');

  test('Extra companies row shows "Cancels on Dec 12, 2026"; no $49 charge in Upcoming billing #b20fe6 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openBilling(page);

    const row = subscriptionRow(page, 'Extra companies');
    await expect(row).toBeVisible();
    await expect(row.getByText('+ 1 company')).toBeVisible();
    await expect(row.getByText('Cancels on Dec 12, 2026')).toBeVisible();

    // Upcoming billing: платежа за отменённое место нет
    const upcoming = page.getByText('Upcoming billing', { exact: true }).locator('xpath=ancestor::*[self::section or self::div][2]');
    await expect(upcoming.getByText('No upcoming charge is scheduled.')).toBeVisible();
    await expect(upcoming.getByText('$49')).toHaveCount(0);
  });
});
